  [inst_1 : NormedAddCommGroup F] [inst_2 : NormedSpace 𝕜 F] {f : 𝕜 → F} {f' : F} {x : 𝕜},
  HasDerivAt f f' x ↔ Filter.Tendsto (slope f x) (nhdsWithin x {x}ᶜ) (nhds f')
@ConvexOn.comp_affineMap : ∀ {𝕜 : Type u_1} {E : Type u_2} {F : Type u_3} {β : Type u_4} [inst : Field 𝕜]
  [inst_1 : LinearOrder 𝕜] [inst_2 : AddCommGroup E] [inst_3 : AddCommGroup F] [inst_4 : AddCommMonoid β]
  [inst_5 : PartialOrder β] [inst_6 : Module 𝕜 E] [inst_7 : Module 𝕜 F] [inst_8 : SMul 𝕜 β] {f : F → β} (g : E →ᵃ[𝕜] F)
  {s : Set F}, ConvexOn 𝕜 s f → ConvexOn 𝕜 (⇑g ⁻¹' s) (f ∘ ⇑g)
