  [inst_1 : NormedAddCommGroup F] [inst_2 : NormedSpace 𝕜 F] {f f₁ : 𝕜 → F} {x : 𝕜},
  f₁ =ᶠ[nhds x] f → deriv f₁ x = deriv f x
@HasFDerivAt.fderiv : ∀ {𝕜 : Type u_1} [inst : NontriviallyNormedField 𝕜] {E : Type u_2} [inst_1 : AddCommGroup E]
  [inst_2 : Module 𝕜 E] [inst_3 : TopologicalSpace E] {F : Type u_3} [inst_4 : AddCommGroup F] [inst_5 : Module 𝕜 F]
  [inst_6 : TopologicalSpace F] {f : E → F} {f' : E →L[𝕜] F} {x : E} [ContinuousAdd E] [ContinuousSMul 𝕜 E]
  [ContinuousAdd F] [ContinuousSMul 𝕜 F] [T2Space F], HasFDerivAt f f' x → fderiv 𝕜 f x = f'
@HasFDerivAt.sum : ∀ {𝕜 : Type u_1} [inst : NontriviallyNormedField 𝕜] {E : Type u_2} [inst_1 : NormedAddCommGroup E]
  [inst_2 : NormedSpace 𝕜 E] {F : Type u_3} [inst_3 : NormedAddCommGroup F] [inst_4 : NormedSpace 𝕜 F] {x : E}
  {ι : Type u_4} {u : Finset ι} {A : ι → E → F} {A' : ι → E →L[𝕜] F},
  (∀ i ∈ u, HasFDerivAt (A i) (A' i) x) → HasFDerivAt (∑ i ∈ u, A i) (∑ i ∈ u, A' i) x
@HasFDerivAt.const_smul : ∀ {𝕜 : Type u_1} [inst : NontriviallyNormedField 𝕜] {E : Type u_2}
  [inst_1 : NormedAddCommGroup E] [inst_2 : NormedSpace 𝕜 E] {F : Type u_3} [inst_3 : NormedAddCommGroup F]
  [inst_4 : NormedSpace 𝕜 F] {f : E → F} {f' : E →L[𝕜] F} {x : E} {R : Type u_4} [inst_5 : Monoid R]
  [inst_6 : DistribMulAction R F] [inst_7 : SMulCommClass 𝕜 R F] [inst_8 : ContinuousConstSMul R F],
  HasFDerivAt f f' x → ∀ (c : R), HasFDerivAt (c • f) (c • f') x
@slope_def_field : ∀ {k : Type u_1} [inst : Field k] (f : k → k) (a b : k), slope f a b = (f b - f a) / (b - a)
@IsOpen.interior_eq : ∀ {X : Type u_1} [inst : TopologicalSpace X] {s : Set X}, IsOpen s → interior s = s
@Convex.affine_preimage : ∀ {𝕜 : Type u_1} {E : Type u_2} {F : Type u_3} [inst : Ring 𝕜] [inst_1 : PartialOrder 𝕜]
  [inst_2 : AddCommGroup E] [inst_3 : AddCommGroup F] [inst_4 : Module 𝕜 E] [inst_5 : Module 𝕜 F] (f : E →ᵃ[𝕜] F)
  {s : Set F}, Convex 𝕜 s → Convex 𝕜 (⇑f ⁻¹' s)
